#include <sys/types.h>
#include <sys/wait.h>
#include <sys/resource.h>
#include <unistd.h>
#include <stdio.h>
#include <stdlib.h>
#include <errno.h>

int main() {
    pid_t pid;
    int wstatus;
    struct rusage usage; 

    pid = fork();

    if (pid == -1) {
        perror("fork failed");
        return EXIT_FAILURE;
    } else if (pid == 0) {
        /* Child process */
        printf("Child (PID %d) running a short task...\n", getpid());
        // Simulate work by iterating
        for (long i = 0; i < 50000000; i++);
        _exit(42);
    } else {
        /* Parent process */
        printf("Parent (PID %d) waiting for child %d...\n", getpid(), pid);

        // Wait for the specific child (pid) and collect resource usage (rusage)
        if (wait4(pid, &wstatus, 0, &usage) == -1) {
            perror("wait4 failed");
            return EXIT_FAILURE;
        }

        if (WIFEXITED(wstatus)) {
            printf("Child terminated with status: %d\n", WEXITSTATUS(wstatus));
        }

        // Print resource usage statistics
        printf("\n--- Resource Usage ---\n");
        printf("User CPU time used: %ld.%06ld seconds\n", 
               usage.ru_utime.tv_sec, usage.ru_utime.tv_usec);
        printf("System CPU time used: %ld.%06ld seconds\n", 
               usage.ru_stime.tv_sec, usage.ru_stime.tv_usec);
    }

    return EXIT_SUCCESS;
}
